class Solution:
    def groupAnagrams(self, words: List[str]) -> List[List[str]]:
        counts, groups = [], []
        for w in words:
            c = [0] * 26
            for ch in w:
                c[ord(ch) - 97] += 1
            for k in range(len(groups)):
                if counts[k] == c:
                    groups[k].append(w)
                    break
            else:
                counts.append(c)
                groups.append([w])
        result = [sorted(g) for g in groups]
        result.sort(key=lambda g: g[0])
        return result

