class Solution {
    public String[][] groupAnagrams(String[] words) {
        List<int[]> counts = new ArrayList<>();
        List<List<String>> groups = new ArrayList<>();
        for (String w : words) {
            int[] c = new int[26];
            for (char ch : w.toCharArray()) c[ch - 'a']++;
            int k = 0;
            while (k < groups.size() && !Arrays.equals(counts.get(k), c)) k++;
            if (k == groups.size()) {
                counts.add(c);
                groups.add(new ArrayList<>());
            }
            groups.get(k).add(w);
        }
        for (List<String> g : groups) Collections.sort(g);
        groups.sort(Comparator.comparing(g -> g.get(0)));
        String[][] out = new String[groups.size()][];
        for (int i = 0; i < out.length; i++) out[i] = groups.get(i).toArray(new String[0]);
        return out;
    }
}

