static int cmpStr(const void* a, const void* b) {
    return strcmp(*(char* const*) a, *(char* const*) b);
}

static int byFirstWord(const void* a, const void* b) {
    return strcmp(((const Group*) a)->words[0], ((const Group*) b)->words[0]);
}

// Sort each group's words, order the groups by their first word, and return them.
static char*** finish(Group* groups, int g, int* returnSize, int** returnColumnSizes) {
    for (int k = 0; k < g; k++) qsort(groups[k].words, groups[k].size, sizeof(char*), cmpStr);
    qsort(groups, g, sizeof(Group), byFirstWord);
    char*** out = malloc(g * sizeof(char**));
    *returnColumnSizes = malloc(g * sizeof(int));
    for (int k = 0; k < g; k++) {
        out[k] = groups[k].words;
        (*returnColumnSizes)[k] = groups[k].size;
    }
    *returnSize = g;
    free(groups);
    return out;
}

