class Solution {
    public String[][] groupAnagrams(String[] words) {
        int n = words.length;
        String[] key = new String[n];
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) {
            char[] c = words[i].toCharArray();
            Arrays.sort(c);
            key[i] = new String(c);
            idx[i] = i;
        }
        Arrays.sort(idx, (a, b) -> {
            int c = key[a].compareTo(key[b]);
            return c != 0 ? c : words[a].compareTo(words[b]);
        });
        List<List<String>> groups = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (i == 0 || !key[idx[i]].equals(key[idx[i - 1]])) groups.add(new ArrayList<>());
            groups.get(groups.size() - 1).add(words[idx[i]]);
        }
        groups.sort(Comparator.comparing(g -> g.get(0)));
        String[][] out = new String[groups.size()][];
        for (int i = 0; i < out.length; i++) out[i] = groups.get(i).toArray(new String[0]);
        return out;
    }
}

