                    typedef struct { char* key; char* word; } Pair;

                    static int cmpChar(const void* a, const void* b) {
                        return *(const char*) a - *(const char*) b;
                    }

                    static int byKeyThenWord(const void* a, const void* b) {
                        const Pair* x = a;
                        const Pair* y = b;
                        int c = strcmp(x->key, y->key);
                        return c ? c : strcmp(x->word, y->word);
                    }

                    char*** groupAnagrams(char** words, int wordsSize, int* returnSize, int** returnColumnSizes) {
                        int n = wordsSize;
                        Pair* pairs = malloc(n * sizeof(Pair));
                        for (int i = 0; i < n; i++) {
                            size_t len = strlen(words[i]);
                            pairs[i].key = malloc(len + 1);
                            memcpy(pairs[i].key, words[i], len + 1);
                            qsort(pairs[i].key, len, 1, cmpChar);
                            pairs[i].word = words[i];
                        }
                        qsort(pairs, n, sizeof(Pair), byKeyThenWord);
                        Group* groups = malloc(n * sizeof(Group));
                        int g = 0;
                        for (int i = 0; i < n;) {
                            int j = i;
                            while (j < n && strcmp(pairs[j].key, pairs[i].key) == 0) j++;
                            groups[g].words = malloc((j - i) * sizeof(char*));
                            groups[g].size = j - i;
                            for (int k = i; k < j; k++) groups[g].words[k - i] = pairs[k].word;
                            g++;
                            i = j;
                        }
                        for (int i = 0; i < n; i++) free(pairs[i].key);
                        free(pairs);
                        return finish(groups, g, returnSize, returnColumnSizes);
                    }

