                    static unsigned long long hashCounts(const int* c) {
                        unsigned long long h = 1469598103934665603ULL;
                        for (int i = 0; i < 26; i++) h = (h ^ (unsigned) c[i]) * 1099511628211ULL;
                        return h;
                    }

                    char*** groupAnagrams(char** words, int wordsSize, int* returnSize, int** returnColumnSizes) {
                        int n = wordsSize;
                        unsigned cap = 1;
                        while (cap < 2u * n) cap <<= 1;
                        int* slot = malloc(cap * sizeof(int));
                        for (unsigned s = 0; s < cap; s++) slot[s] = -1;
                        int (*counts)[26] = malloc(n * sizeof *counts);
                        int* gid = malloc(n * sizeof(int));
                        int* size = calloc(n, sizeof(int));
                        int g = 0;
                        for (int i = 0; i < n; i++) {
                            int c[26] = {0};
                            for (char* p = words[i]; *p; p++) c[*p - 'a']++;
                            unsigned s = (unsigned) (hashCounts(c) >> 32) & (cap - 1);
                            while (slot[s] != -1 && memcmp(counts[slot[s]], c, sizeof c) != 0) s = (s + 1) & (cap - 1);
                            if (slot[s] == -1) {
                                memcpy(counts[g], c, sizeof c);
                                slot[s] = g++;
                            }
                            gid[i] = slot[s];
                            size[slot[s]]++;
                        }
                        Group* groups = malloc(g * sizeof(Group));
                        for (int k = 0; k < g; k++) {
                            groups[k].words = malloc(size[k] * sizeof(char*));
                            groups[k].size = 0;
                        }
                        for (int i = 0; i < n; i++) groups[gid[i]].words[groups[gid[i]].size++] = words[i];
                        free(slot);
                        free(counts);
                        free(gid);
                        free(size);
                        return finish(groups, g, returnSize, returnColumnSizes);
                    }
